/* MSG-01 · panel de contenido de la pantalla de hilos.
   Solo se leen colores de los tokens globales — ningún valor literal. */

.page {
  min-width: 0;
}

.eyebrow {
  margin: 0 0 4px;
  color: var(--bw-steel-mist);
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.title {
  margin: 0 0 3px;
  color: var(--bw-deep-steel);
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  line-height: 1.3;
}

.subtitle {
  max-width: 560px;
  margin: 0 0 16px;
  color: var(--bw-steel-mist);
  font-size: 14px;
  line-height: 1.6;
}

.e2eeStatus {
  display: flex;
  align-items: center;
  gap: 8px;
  width: fit-content;
  margin: 0 0 14px;
  padding: 6px 10px;
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: 5px;
  color: var(--bw-signal-green);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  letter-spacing: 0.04em;
  line-height: 1.2;
  text-transform: uppercase;
}

.e2eeStatus i {
  font-size: 12px;
}

/* ── Barra de acciones ─────────────────────────────────────────────────── */

.actionsBar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchForm {
  position: relative;
  flex: 1 1 180px;
  max-width: 300px;
  margin: 0;
}

.searchForm > i {
  position: absolute;
  top: 50%;
  left: 10px;
  pointer-events: none;
  color: var(--bw-input-placeholder);
  font-size: 15px;
  transform: translateY(-50%);
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 12px 0 32px;
  outline: none;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  color: var(--bw-deep-steel);
  font-family: inherit;
  font-size: 13px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.dirAction {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
}

.primaryBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-on-dark-hover);
  cursor: pointer;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.primaryBtn i {
  font-size: 16px;
}

.primaryBtn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.scopeNote {
  color: var(--bw-hint-steel);
  font-size: 10px;
  letter-spacing: var(--bw-ls-hint);
  line-height: 1.2;
  text-align: center;
  text-transform: uppercase;
}

.threadCount {
  margin-left: auto;
  color: var(--bw-input-placeholder);
  font-size: 12px;
  white-space: nowrap;
}

/* ── Estados intermedios ───────────────────────────────────────────────── */

.loading {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 13px 16px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  color: var(--bw-steel-mist);
  font-size: 13px;
}

.alert {
  padding: 12px 14px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: 6px;
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
}

/* ── Paginación ────────────────────────────────────────────────────────── */

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  font-family: inherit;
  font-size: 12px;
  transition: border-color 0.12s ease, color 0.12s ease;
}

.pageBtn:hover:not(:disabled):not(.active) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.pageBtn:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: 1px;
}

.pageBtn:disabled {
  cursor: default;
  color: var(--bw-input-placeholder);
}

.pageBtn.active {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-on-dark-hover);
  cursor: default;
}

