import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';

import type { MemberProfile } from '../../lib/session';
import { fetchThreadPage, pageCount, type ThreadPage } from '../../lib/threads';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date | undefined;
  /**
   * F-118: esta prop forma parte de la firma pública porque App.tsx la cablea,
   * pero MSG-02 no está en el alcance del MVP. Se recibe y se ignora.
   */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Convierte un fallo de red en texto para el usuario.
 *
 * PostgREST no rechaza con `Error`: lanza un objeto plano `{ code, message }`,
 * así que `String(e)` daría `[object Object]` y `e.message` sería `undefined`.
 * Se extraen `code` y `message` cuando existen y se pintan junto a la frase
 * para humanos (F-020/F-128).
 */
function errorDetail(error: unknown): string {
  if (error && typeof error === 'object') {
    const candidate = error as { code?: unknown; message?: unknown };
    const code = typeof candidate.code === 'string' ? candidate.code : '';
    const message = typeof candidate.message === 'string' ? candidate.message : '';
    if (code && message) return `${code}: ${message}`;
    if (code) return code;
    if (message) return message;
  }
  if (error instanceof Error) return error.message;
  return String(error);
}

/**
 * Pantalla MSG-01 · Lista de Hilos.
 *
 * Es LA pantalla, no un componente de presentación: posee el estado de búsqueda,
 * el de página y la consulta a `fetchThreadPage`.
 */
export function Messages({ profile, now = new Date() }: MessagesProps) {
  const [input, setInput] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [pageData, setPageData] = useState<ThreadPage>({ threads: [], total: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);

  useEffect(() => {
    let alive = true;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((result) => {
        if (alive) setPageData(result);
      })
      .catch((err: unknown) => {
        if (alive) setError(err);
      })
      .finally(() => {
        if (alive) setLoading(false);
      });

    return () => {
      alive = false;
    };
  }, [profile.orgId, search, page]);

  function submitSearch(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    setSearch(input.trim());
    setPage(1);
  }

  const totalPages = pageCount(pageData.total);

  return (
    <div className={styles.page}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.subtitle}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a
        extremo.
      </p>

      <div className={styles.e2eeStatus}>
        <i className="ti ti-lock" aria-hidden="true" />
        <span>E2EE activo · claves en memoria de sesión · contenido descifrado localmente</span>
      </div>

      <div className={styles.actionsBar}>
        <form role="search" className={styles.searchForm} onSubmit={submitSearch}>
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            aria-label="Buscar por nombre de organización"
            value={input}
            onChange={(event) => setInput(event.target.value)}
          />
        </form>

        <div className={styles.dirAction}>
          <button type="button" className={styles.primaryBtn} disabled>
            <i className="ti ti-address-book" aria-hidden="true" />
            Nuevo contacto
          </button>
          {/* F-139: el motivo visible del botón deshabilitado. */}
          <span className={styles.scopeNote} data-testid="directorio-scope">
            Fuera del MVP
          </span>
        </div>

        {/* F-138: el span con el contador de resultados lleva este testid. */}
        <span className={styles.threadCount} data-testid="pag-info">
          {pageData.total} {pageData.total === 1 ? 'hilo' : 'hilos'} · Página {page} de {totalPages}
        </span>
      </div>

      {loading ? (
        <div className={styles.loading} role="status">
          <i className="ti ti-loader" aria-hidden="true" />
          Cargando hilos…
        </div>
      ) : error ? (
        <div className={styles.alert} role="alert">
          <strong>No se pudieron cargar los hilos.</strong> {errorDetail(error)}
        </div>
      ) : (
        <>
          <ThreadList
            threads={pageData.threads}
            now={now}
            onOpen={() => {
              /* MSG-02 no está en el alcance: no hay destino al que navegar. */
            }}
          />
          <nav className={styles.pagination} aria-label="Paginación de hilos">
            <button
              type="button"
              className={styles.pageBtn}
              aria-label="Página anterior"
              disabled={page <= 1}
              onClick={() => setPage(page - 1)}
            >
              ‹
            </button>
            {Array.from({ length: totalPages }, (_, index) => index + 1).map((pageNumber) => (
              <button
                key={pageNumber}
                type="button"
                className={`${styles.pageBtn} ${pageNumber === page ? styles.active : ''}`}
                aria-current={pageNumber === page ? 'page' : undefined}
                onClick={() => setPage(pageNumber)}
              >
                {pageNumber}
              </button>
            ))}
            <button
              type="button"
              className={styles.pageBtn}
              aria-label="Página siguiente"
              disabled={page >= totalPages}
              onClick={() => setPage(page + 1)}
            >
              ›
            </button>
          </nav>
        </>
      )}
    </div>
  );
}

