/* MSG-01 · filas de la lista de hilos.
   Solo se leen colores de los tokens globales — ningún valor literal. */

.list {
  margin: 0;
  padding: 0;
  list-style: none;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  display: block;
  margin: 0;
  padding: 0;
}

.row:last-child .rowMain {
  border-bottom: none;
}

.rowMain {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  align-items: center;
  width: 100%;
  padding: 14px 18px;
  background: var(--bw-surface-mist);
  border: none;
  border-bottom: 1px solid var(--bw-divider-mist);
  cursor: pointer;
  font-family: inherit;
  font-size: inherit;
  color: inherit;
  text-align: left;
  transition: background 0.12s ease;
}

.rowMain:hover {
  background: var(--bw-hover-surface);
}

.rowMain:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.rowTop {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.orgName {
  overflow: hidden;
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.countryBadge {
  flex-shrink: 0;
  padding: 2px 6px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  line-height: 1.2;
  white-space: nowrap;
}

.tsSide {
  justify-self: end;
  color: var(--bw-input-placeholder);
  font-family: var(--bw-font-mono);
  font-size: 10px;
  line-height: 1.2;
  white-space: nowrap;
}

.preview {
  min-width: 0;
  overflow: hidden;
  color: var(--bw-steel-mist);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.stateBadge {
  justify-self: end;
  padding: 2px 7px;
  border: 1px solid var(--bw-badge-neutral-border);
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  line-height: 1.3;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

.neutral {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
}

/* Sin token propio de borde de badge azul: se usa el borde más cercano, el del
   chip activo, que comparte la misma base de color. */
.info {
  background: var(--bw-chip-active-bg);
  border-color: var(--bw-chip-active-border);
  color: var(--bw-calibration-blue);
}

.warn {
  background: var(--bw-badge-warning-bg);
  border-color: var(--bw-badge-warning-border);
  color: var(--bw-warning);
}

.success {
  background: var(--bw-badge-success-bg);
  border-color: var(--bw-badge-success-border);
  color: var(--bw-signal-green);
}

.closed {
  background: var(--bw-badge-neutral-bg);
  border-color: var(--bw-badge-neutral-border-soft);
  color: var(--bw-input-placeholder);
  text-decoration: line-through;
}

