  gap: 6px;
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  color: var(--bw-on-dark-hover);
  cursor: pointer;
  font-family: inherit;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
}

.primaryBtn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}

.scopeNote {
  margin: 0;
  color: var(--bw-hint-steel);
  font-size: 10px;
  letter-spacing: var(--bw-ls-hint);
  line-height: 1.3;
  text-transform: uppercase;
}

