import { previewLabel, relativeTime, stateTone, type StateTone, type ThreadSummary } from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj (F-024). */
  now?: Date | undefined;
  onOpen: (id: string) => void;
}

/** Estado -> clase CSS del badge. El color exacto vive en el módulo CSS. */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.neutral,
  info: styles.info,
  warn: styles.warn,
  success: styles.success,
  closed: styles.closed,
};

/**
 * Lista de hilos de MSG-01, presentacional.
 *
 * Las filas llegan ya ordenadas por `last_item_at` descendente: el orden es del
 * servidor y este componente no lo vuelve a tocar. Cada fila es un `li` con un
 * `button` dentro — nunca `<li role="button">`, que rompería el rol `listitem`
 * que el contrato consulta (F-131).
 */
export function ThreadList({ threads, now, onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <i className={`${styles.emptyIcon} ti ti-messages-off`} aria-hidden="true" />
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        <button type="button" className={styles.primaryBtn} disabled>
          Ir al Directorio
        </button>
        <p className={styles.scopeNote}>El Directorio queda fuera del MVP</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const tone = stateTone(thread.state);
        const ago = now
          ? relativeTime(thread.lastItemAt, now)
          : relativeTime(thread.lastItemAt);

        return (
          <li key={thread.id} className={styles.row}>
            <button
              type="button"
              className={styles.rowMain}
              aria-label={`Abrir hilo con ${thread.counterpartyName}`}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.rowTop}>
                <span className={styles.orgName}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry ? (
                  <span className={styles.countryBadge}>{thread.counterpartyCountry}</span>
                ) : null}
              </span>
              <span className={styles.tsSide}>{ago}</span>
              <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
              <span className={`${styles.stateBadge} ${TONE_CLASS[tone]}`}>
                {thread.state}
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
